# Print, for translate.ps1, the characters that check.pl (inside translate.sh)
# gives extra weight, as .NET regular-expression character classes.
#
#   /usr/bin/perl calibration/script-ranges.pl
#
# .NET has no \p{Han} or \p{Arabic}: it knows Unicode blocks, not scripts. So
# translate.ps1 carries the ranges, taken here from perl's own tables so that
# the two helpers count the same characters. Paste the output over the lines
# between "generated by" and "end of generated" in translate.ps1. Use the perl
# that macOS ships, which is the one translate.sh runs.
#
# Only the Basic Multilingual Plane: translate.ps1 handles the characters
# beyond it itself (it counts planes 2 and 3 as Han and nothing else).
use strict; use warnings;

# The same expressions as @WEIGHT in check.pl, in the same order.
my @SCRIPTS = (
  [Han    => qr/(?=[\p{L}\p{N}])\p{Han}/],
  [Kana   => qr/(?=\p{L})[\p{Hiragana}\p{Katakana}]/],
  [Hangul => qr/(?=\p{L})\p{Hangul}/],
  [Hebrew => qr/(?=\p{L})\p{Hebrew}/],
  [Arabic => qr/(?=\p{L})\p{Arabic}/],
  [Indic  => qr/(?=\p{L})[\p{Devanagari}\p{Bengali}\p{Gurmukhi}\p{Gujarati}\p{Tamil}\p{Telugu}\p{Kannada}\p{Malayalam}\p{Sinhala}]/],
);

printf "  # generated by calibration/script-ranges.pl with perl %vd (Unicode %s)\n", $^V, Unicode::UCD::UnicodeVersion();
for my $s (@SCRIPTS) {
  my ($name, $re) = @$s;
  my (@ranges, $start, $prev);
  for my $cp (0 .. 0xFFFF) {
    next if $cp >= 0xD800 && $cp <= 0xDFFF;
    next unless chr($cp) =~ $re;
    if (defined $prev && $cp == $prev + 1) { $prev = $cp; next }
    push @ranges, [$start, $prev] if defined $start;
    ($start, $prev) = ($cp, $cp);
  }
  push @ranges, [$start, $prev] if defined $start;
  my $class = join '', map { $_->[0] == $_->[1] ? sprintf('\\u%04X', $_->[0]) : sprintf('\\u%04X-\\u%04X', @$_) } @ranges;
  printf "  %-6s = '%s'\n", $name, $class;
}
print "  # end of generated\n";

BEGIN { require Unicode::UCD }
